import{z as o,x as A,o as B,c as d,q as l,j as i,D as e,d as r,s as n,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"实时调度对照","description":"","frontmatter":{"title":"实时调度对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/realtime-sched.md","filePath":"cs/realtime-sched.md","lastUpdated":1791413859000}'),p={name:"cs/realtime-sched.md"};function m(C,E,D,u,F,c){const t=A("Mermaid");return B(),d("div",null,[E[2]||(E[2]=l('<h1 id="实时调度对照" tabindex="-1">实时调度对照 <a class="header-anchor" href="#实时调度对照" aria-label="Permalink to &quot;实时调度对照&quot;">​</a></h1><div class="epigraph"><p>实时系统的正确性依赖于逻辑结果以及结果产生的时间。</p><footer>—— 据 Liu and Layland, Scheduling Algorithms for Multiprogramming in a Hard-Real-Time Environment, 1973 整理</footer></div><p><a href="/cs/load-balance-migrate">上一课</a>用虚拟时间摊份额，优化的是公平与平均响应。控制回路、多媒体截止时间要的是「在 \\(T\\) 之前跑完」，份额再公平也可能全体逾期。缺口是对照：<strong>周期任务、截止时间、可调度性</strong>，而不是再调 nice。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硬实时：错过期限即失败；软实时：错过可贬值但仍希望少错过。任务常写成周期 \\(P\\)、最坏执行 \\(C\\)、截止 \\(D\\)（常取 \\(D=P\\)）。缺口不是 PCB 新字段的清单，而是问：给定一组 \\((C_i,P_i)\\)，固定优先级或动态优先级能否让所有截止满足。</p><p><span class="marginnote">术语翻译：硬实时像刹车控制器——结果晚了等于没做，甚至酿成事故；软实时像视频播放——偶尔丢一帧画面有点卡，但程序不判失败。两者的工程态度完全不同：前者要求「保证绝不迟」（可调度性证明），后者只要「绝大多数不迟」（统计与缓冲兜底）。</span></p><p>本课只引入率单调（RM）与最早截止优先（EDF）的对照，不把全部响应时间分析写完。</p><p><span class="marginnote">Liu 与 Layland：周期任务、抢占、独立、同时在周期起点就绪。RM 按周期长短定优先级；利用率不超过 \\(n(2^{1/n}-1)\\) 则 RM 可调度。EDF 界限是 \\(1\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>RM：周期越短优先级越高，静态。EDF：谁的绝对截止更早谁跑，动态。两者都假定可抢占、忽略切换税（教学）。若还有 CFS 那种公平份额与实时队列并存，实时队列必须先于公平队列，否则期限被后台编译吞掉。</p><p><span class="marginnote">数字实例：两个任务 RM 的利用界限是 \\(2(\\sqrt2-1)\\approx 0.83\\)，即总利用率超过 83% 时不能闭眼判可调度；EDF 的界限是 1，利用率 99% 仍保证全部按时。代价是 EDF 要在运行时维护绝对截止、过载时行为更难预测——静态与动态的取舍在这两个数字里。</span></p>',11)),(B(),i(s,null,{default:e(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFS%5B%22%E5%85%AC%E5%B9%B3%E4%BB%BD%E9%A2%9D%3A%20%E5%B9%B3%E5%9D%87%E6%8C%87%E6%A0%87%22%5D%20--%3E%20CONTRAST%5B%22%E5%AF%B9%E7%85%A7%22%5D%0A%20%20RT%5B%22%E6%9C%9F%E9%99%90%3A%20RM%20%2F%20EDF%22%5D%20--%3E%20CONTRAST%0A%20%20CONTRAST%20--%3E%20SIG%5B%22%E5%90%8E%E8%AF%BE%3A%20%E4%BF%A1%E5%8F%B7%E7%AD%89%E5%BC%82%E6%AD%A5%E4%BA%8B%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"优先级反转（锁被低优先级占着）本课点名存在，展开要等锁课。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"CFS 最小化的是虚拟时间差；RM/EDF 最小化的是逾期。同一条线程不能同时用两套目标当主策略：实时线程若仍被 vruntime 拉平，期限无意义。通用操作系统因此把策略分类——分时一类，实时一类——而不是「更小的时间片」。",-1)),E[6]||(E[6]=a("p",null,"最坏执行 \\(C\\) 必须真是上界；缓存与中断下半部会把 \\(C\\) 拉长，所以实时系统还要限制 ISR。本课不写 WCET 测量。",-1)),(B(),i(s,null,{default:e(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%90%8C%E4%B8%80%E6%A0%B8%E4%B8%8A%E4%B8%A4%E7%B1%BB%E7%BA%BF%E7%A8%8B%E5%B9%B6%E5%AD%98%22%5D%20--%3E%20Q%7B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E5%90%AC%E8%B0%81%E7%9A%84%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E6%8C%89%20CFS%20%E5%85%AC%E5%B9%B3%E4%BB%BD%E9%A2%9D%22%7C%20V%5B%22vruntime%20%E6%8B%89%E5%B9%B3%EF%BC%9A%E6%8E%A7%E5%88%B6%E5%9B%9E%E8%B7%AF%E5%88%86%E5%88%B0%E9%9B%B6%E7%A2%8E%E6%97%B6%E9%97%B4%22%5D%0A%20%20V%20--%3E%20MISS%5B%22%E9%80%BB%E8%BE%91%E7%BB%93%E6%9E%9C%E6%AD%A3%E7%A1%AE%EF%BC%8C%E4%BD%86%E9%94%99%E8%BF%87%E4%BA%86%E6%88%AA%E6%AD%A2%22%5D%0A%20%20Q%20--%3E%7C%22%E5%AE%9E%E6%97%B6%E9%98%9F%E5%88%97%E4%BC%98%E5%85%88%E4%BA%8E%E5%88%86%E6%97%B6%22%7C%20D%5B%22RM%2FEDF%20%E5%85%88%E6%BB%A1%E8%B6%B3%20C%E3%80%81P%E3%80%81D%22%5D%0A%20%20D%20--%3E%20OK%5B%22%E6%9C%9F%E9%99%90%E5%86%85%E5%AE%8C%E6%88%90%EF%BC%8C%E5%89%A9%E4%BD%99%E6%97%B6%E9%97%B4%E5%86%8D%E7%BB%99%E5%88%86%E6%97%B6%22%5D%0A%20%20OK%20--%3E%20B%5B%22%E5%90%8E%E5%8F%B0%E7%BC%96%E8%AF%91%E4%B8%8D%E5%86%8D%E5%90%9E%E6%8E%89%E6%9C%9F%E9%99%90%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<p><span class="marginnote">为什么重要：这一步做错了，可调度性证明再漂亮也白搭。设控制回路的 \\(C\\) 实测 5ms，但没算进缓存污染后的 6.5ms——期限 8ms 时看似余量 3ms，实际只剩 1.5ms，一次中断风暴就逾期。WCET 不是估计值而是带安全系数的上界，测小了整张可调度表都会作废。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 POSIX <code>SCHED_DEADLINE</code> 的 CBS 服务器写完，不引入弱硬实时的 \\(m\\)-in-\\(k\\) 模型。也不声称桌面 Linux 默认就是硬实时：那是配置与补丁的问题，主干只对照目标函数。</p><p>弱实时多媒体常用软期限加缓冲；不要把桌面音频 droop 当成 Liu–Layland 硬实时失败。</p><p>后课默认：分时看份额，实时看期限。异步事件如何打断用户线程（仍非设备 IRQ），是后面信号课的事；下一课把 RM 收成可检查的规则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公平摊时间不保证截止；RM/EDF 才对着 \\((C,P)\\) 说话。</li><li>实时队列必须能抢占分时队列。</li><li>锁引起的优先级反转留到同步课。</li><li>出处：Liu and Layland, <em>JACM</em> 1973；Silberschatz et al., <em>OSC</em> 实时调度。</li></ul>',7))])}const T=o(p,[["render",m]]);export{S as __pageData,T as default};
